<?php
declare(strict_types=1); namespace App\Http\Controllers\Personnel;
use App\Http\Controllers\Controller;use App\Http\Requests\Personnel\UpdatePersonnelAccountRequest;use App\Models\{Personnel,User};use App\Services\Personnel\{PersonnelRoleSuggestionService,PersonnelService};use Illuminate\Http\{RedirectResponse,Request};use Illuminate\View\View;
class PersonnelAccountController extends Controller {public function __construct(private PersonnelService $service,private PersonnelRoleSuggestionService $suggestions){}public function edit(Personnel $personnel):View{return view('personnel.account',['title'=>'Hubungkan Akun','personnel'=>$personnel->load('user.roles'),'accounts'=>User::whereDoesntHave('personnel')->with('roles')->orderBy('name')->get(),'suggestedRole'=>$this->suggestions->suggest($personnel)]);}public function update(UpdatePersonnelAccountRequest $r,Personnel $personnel):RedirectResponse{$this->service->connect($personnel,(int)$r->validated('user_id'),$r->user(),$r->boolean('apply_suggested_role'));return redirect()->route('personnel.show',$personnel)->with('status','Akun berhasil dihubungkan dengan personalia.');}public function destroy(Request $r,Personnel $personnel):RedirectResponse{$this->service->disconnect($personnel,$r->user());return back()->with('status','Hubungan akun berhasil dilepaskan.');}}
